<script setup>import {ref,onMounted} from 'vue';import api from '../../services/api';const programs=ref([]),links=ref([]);onMounted(async()=>{try{programs.value=(await api.get('/affiliate-programs')).data.programs||[];links.value=(await api.get('/affiliate-links/mine')).data.links||[]}catch(e){}})</script><template><section><div class="rounded-3xl bg-indigo-600 p-8 text-white"><p class="font-bold uppercase tracking-wider text-indigo-200">Affiliate program</p><h1 class="mt-2 text-4xl font-black">Turn recommendations into earnings.</h1><p class="mt-3 max-w-2xl text-indigo-100">Share approved product links and track clicks, conversions and commissions.</p></div><h2 class="mt-10 text-xl font-black">Available programs</h2><div class="mt-4 grid gap-4 md:grid-cols-2"><div v-for="p in programs" :key="p.id" class="rounded-2xl border bg-white p-5"><b>{{p.name}}</b><p class="mt-2 text-slate-500">{{p.commissionType==='percentage'?p.commissionRate+'%':'Fixed commission '+p.fixedCommission}}</p></div></div><h2 class="mt-10 text-xl font-black">My links</h2><div class="mt-4 rounded-2xl border bg-white p-5"><div v-for="l in links" :key="l.id" class="border-b py-3 last:border-0"><b>{{l.code}}</b><span class="ml-3 text-sm text-slate-500">{{l.clicks||0}} clicks · {{l.conversions||0}} conversions</span></div><span v-if="!links.length" class="text-slate-500">No affiliate links yet.</span></div></section></template>